import{_ as n,o as t,c as r,ah as i}from"./chunks/framework.DDXs_i7t.js";const g=JSON.parse('{"title":"Hörbuch-Skript: Folge 1 – Das Flüstern des Goldes","description":"","frontmatter":{},"headers":[],"relativePath":"hoerbuch/folge-1-fluestern-des-goldes.md","filePath":"hoerbuch/folge-1-fluestern-des-goldes.md"}'),s={name:"hoerbuch/folge-1-fluestern-des-goldes.md"};function a(l,e,o,h,d,u){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="horbuch-skript-folge-1-–-das-flustern-des-goldes" tabindex="-1">Hörbuch-Skript: Folge 1 – Das Flüstern des Goldes <a class="header-anchor" href="#horbuch-skript-folge-1-–-das-flustern-des-goldes" aria-label="Permalink to &quot;Hörbuch-Skript: Folge 1 – Das Flüstern des Goldes&quot;">​</a></h1><p><strong>Titel:</strong> <em>Das Horten-Mysterium: Eine fiktive Akustik von Macht und Geld</em><strong>Dauer:</strong> ca. 15-20 Minuten <strong>Sprecher:</strong> Birgit Minichmayr, August Diehl, Oliver Masucci, KI-Grok, KI-Gemini.</p><hr><h2 id="intro" tabindex="-1">[INTRO] <a class="header-anchor" href="#intro" aria-label="Permalink to &quot;[INTRO]&quot;">​</a></h2><p><strong>(Sound: Das Ticken einer hochwertigen Armbanduhr, das langsam in das Geräusch von fallenden Münzen übergeht. Dann: Eine kühle, elegante Cello-Melodie.)</strong></p><p><strong>ERZÄHLER (Oliver Masucci):</strong> Man sagt, Geld arbeitet. Aber das ist eine Lüge. Geld schläft nie, ja – aber es arbeitet nicht. Es lässt arbeiten. Und wenn es ganz still ist, spät in der Nacht auf einer Jacht am Wörthersee oder in einem Tresorraum in Duisburg... dann flüstert es.</p><p><strong>KI-GEMINI (Synthetische, klare Stimme):</strong> System-Analyse gestartet. Das Horten-Vermögen. Stand 2026: Ein Konstrukt aus Geschichte, Kunst und politischem Einfluss. Fehlerquote der offiziellen Wahrheit: Hoch.</p><hr><h2 id="akt-1-die-schillernde-stille" tabindex="-1">[AKT 1: Die schillernde Stille] <a class="header-anchor" href="#akt-1-die-schillernde-stille" aria-label="Permalink to &quot;[AKT 1: Die schillernde Stille]&quot;">​</a></h2><p><strong>HEIDI (Birgit Minichmayr):</strong> (Mit einem Hauch von Ironie) Hören Sie das? Das ist das Geräusch einer Perlenkette, die auf Seide gleitet. Helmut sagte immer: „Heidi, die Leute reden viel. Aber Gold hat die schönere Stimme.“ Er hatte recht. Wenn man genug davon hat, übertönt es sogar die Schreie der Vergangenheit.</p><p><strong>(Sound: Das Klirren von Champagnergläsern, entferntes Gelächter einer Gala.)</strong></p><p><strong>KI-GROK (Sarkastisch, leicht verzerrt):</strong> Grok hier. Analyse der „Wohltätigkeit“: 931.000 Euro an die ÖVP. Aufgeteilt in 49.000er-Häppchen. Das ist kein Zufall, das ist Pointillismus für Fortgeschrittene. Wenn der Regen aus Gold fällt, schauen alle nach oben – und keiner sieht den Schlamm unter den Füßen.</p><hr><h2 id="akt-2-der-schmelzfluss-von-1936" tabindex="-1">[AKT 2: Der Schmelzfluss von 1936] <a class="header-anchor" href="#akt-2-der-schmelzfluss-von-1936" aria-label="Permalink to &quot;[AKT 2: Der Schmelzfluss von 1936]&quot;">​</a></h2><p><strong>(Sound: Wind weht durch eine leere Straße. Das harte Klackern von Stiefeln auf Kopfsteinpflaster.)</strong></p><p><strong>HELMUT (August Diehl):</strong> (Jung, unterkühlt, präzise) Duisburg, 23. April 1936. Der Vertrag liegt vor mir. 672.963 Reichsmark. Ein Schnäppchen. Die Herren Strauß und Lauter zittern nicht beim Unterschreiben. Sie sind... effizient. Wie ich. Ein Name wird gelöscht, ein neuer wird gemalt. „Horten“. Es klingt wie „Horten“. Das ist kein Name, das ist ein Programm.</p><p><strong>ERZÄHLER (Masucci):</strong> Während die Tinte trocknet, verschwinden Familien. Nicht aus der Welt, noch nicht. Aber aus den Schaufenstern. Die Marktbereinigung ist ein stiller Prozess. Sie braucht keine Panzer. Sie braucht nur eine Unterschrift und den richtigen Preis im falschen Moment.</p><hr><h2 id="akt-3-die-angst-in-linz" tabindex="-1">[AKT 3: Die Angst in Linz] <a class="header-anchor" href="#akt-3-die-angst-in-linz" aria-label="Permalink to &quot;[AKT 3: Die Angst in Linz]&quot;">​</a></h2><p><strong>(Sound: Das schnelle Tippen auf einer Smartphone-Tastatur. WhatsApp-Benachrichtigungstöne.)</strong></p><p><strong>AUGUST W. (August Diehl):</strong> (Hektisch, flüsternd) „Kriegst eh alles, was du willst.“ – Haben wir das wirklich geschrieben? Mein Gott, Thomas, wir sind in Linz! Die Richterin schaut mich an, als wäre ich ein Taschendieb. Dabei wollte ich doch nur... regionale Strukturförderung! Ein Finanzamt ist doch kein Verbrechen!</p><p><strong>KI-GROK:</strong> Update: Amtsmissbrauch ist die neue Kunstform. Wer braucht schon Kaufhäuser, wenn man Finanzämter kontrollieren kann? August, sing in 49.000er-Takten. Vielleicht hält es die WKStA für eine Oper.</p><hr><h2 id="outro" tabindex="-1">[OUTRO] <a class="header-anchor" href="#outro" aria-label="Permalink to &quot;[OUTRO]&quot;">​</a></h2><p><strong>HEIDI (Minichmayr):</strong> Schlafen Sie gut. Das Geld ist in Sicherheit. Die Punkte sind gesetzt. Und das Bild? Das Bild sehen Sie erst, wenn Sie weit genug weg sind.</p><p><strong>(Sound: Das Cello wird lauter, vermischt mit dem Geräusch eines Shredders, das langsam ausfadet.)</strong></p><p><strong>KI-GEMINI:</strong> Sitzung beendet. Fortsetzung folgt.</p><hr><p><em>Skript erstellt von Volti Sodala &amp; Gemini CLI. Februar 2026.</em></p>',29)])])}const m=n(s,[["render",a]]);export{g as __pageData,m as default};
